-- 00_PRECHECK — 조회 전용 (전체 F5 · 값 입력 없음). [E20261102-DMF0082HINT] 적용 전 상태
-- L0 접속 DB · PKG 상태 · L1 앵커 첫 줄 (GET_MAIN_DATA 범위 줄 기준 — H1 2 이하, 나머지 1 이상이면 진행. 최종 판정은 10 이 앵커 전체로 한다) · L2 마커 0 · L3 실행 중 세션
SET DEFINE OFF
SELECT 'L0' CHK, SYS_CONTEXT('USERENV','DB_NAME') DB_NAME, USER CUR_USER, TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI:SS') NOW FROM DUAL;
SELECT 'L0' CHK, OBJECT_TYPE, STATUS, TO_CHAR(LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL FROM USER_OBJECTS WHERE OBJECT_NAME='PKG_DMF0082' ORDER BY OBJECT_TYPE;
WITH B AS (SELECT (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND RTRIM(TEXT, CHR(10)||CHR(13)) = 'PROCEDURE P_DMF0082_GET_MAIN_DATA') L1,
                  (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE 'PROCEDURE P_DMF0082_POPUP_GET_FUTUREPRICE_INFO%') L2 FROM DUAL)
SELECT 'H1' ANCHOR, COUNT(*) N_RANGE FROM USER_SOURCE S, B WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND S.LINE BETWEEN B.L1 AND B.L2 AND RTRIM(S.TEXT, CHR(10)||CHR(13)) LIKE '    SELECT F.DIVISION_ID'
UNION ALL SELECT 'H2' ANCHOR, COUNT(*) N_RANGE FROM USER_SOURCE S, B WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND S.LINE BETWEEN B.L1 AND B.L2 AND RTRIM(S.TEXT, CHR(10)||CHR(13)) LIKE '    INSERT INTO SCM_MGR.GT_DMF0082_T_LAST_DATA_SETUP_FCST'
UNION ALL SELECT 'H3' ANCHOR, COUNT(*) N_RANGE FROM USER_SOURCE S, B WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND S.LINE BETWEEN B.L1 AND B.L2 AND RTRIM(S.TEXT, CHR(10)||CHR(13)) LIKE '        SELECT A.DIVISION_ID AS C01'
UNION ALL SELECT 'H4' ANCHOR, COUNT(*) N_RANGE FROM USER_SOURCE S, B WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND S.LINE BETWEEN B.L1 AND B.L2 AND RTRIM(S.TEXT, CHR(10)||CHR(13)) LIKE '        SELECT /*+ LEADING(A) USE_HASH(B) USE_HASH(C) */ %'
UNION ALL SELECT 'H5' ANCHOR, COUNT(*) N_RANGE FROM USER_SOURCE S, B WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND S.LINE BETWEEN B.L1 AND B.L2 AND RTRIM(S.TEXT, CHR(10)||CHR(13)) LIKE '    SELECT F.DIVISION_ID, F.PROJECT_CODE, F.END_CUSTOMER, F.SCM_SITE_ID, F.ITEM_ID'
UNION ALL SELECT 'H6a' ANCHOR, COUNT(*) N_RANGE FROM USER_SOURCE S, B WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND S.LINE BETWEEN B.L1 AND B.L2 AND RTRIM(S.TEXT, CHR(10)||CHR(13)) LIKE '    SELECT [@V_COLUMN]'
UNION ALL SELECT 'H6b' ANCHOR, COUNT(*) N_RANGE FROM USER_SOURCE S, B WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND S.LINE BETWEEN B.L1 AND B.L2 AND RTRIM(S.TEXT, CHR(10)||CHR(13)) LIKE '    V_SQL := REPLACE(V_SQL, ''[@V_QTY_SUM]'',     V_QTY_SUM);';
SELECT 'L2 마커' CHK, COUNT(*) N, CASE WHEN COUNT(*) = 0 THEN '미적용 (기대)' ELSE '적용됨 — 10 재실행은 무동작' END JUDGE
  FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%E20261102-DMF0082HINT%';
SELECT 'L3 실행중' CHK, S.INST_ID, S.SID, S.SERIAL#, S.USERNAME, S.LAST_CALL_ET CALL_SEC
  FROM GV$SESSION S WHERE S.TYPE='USER' AND S.STATUS='ACTIVE'
   AND S.PLSQL_ENTRY_OBJECT_ID = (SELECT OBJECT_ID FROM USER_OBJECTS WHERE OBJECT_NAME='PKG_DMF0082' AND OBJECT_TYPE='PACKAGE');
